import { useRef, type ReactNode } from "react";
import { Button } from "./button";
import { cn } from "./utils";

export type MediaRailItem = { id: string; label: string; preview: ReactNode };
export type MediaRailProps = {
    label: string;
    items: readonly MediaRailItem[];
    value?: string;
    onValueChange: (id: string) => void;
    className?: string;
};

export function MediaRail({ label, items, value, onValueChange, className }: MediaRailProps) {
    const rail = useRef<HTMLDivElement>(null);
    if (!label.trim() || items.some(item => !item.id.trim() || !item.label.trim()) || new Set(items.map(item => item.id)).size !== items.length) throw new Error("MediaRail requires a label and unique named items.");
    if (value !== undefined && !items.some(item => item.id === value)) throw new Error("MediaRail value must identify an item.");
    const move = (direction: number) => {
        const element = rail.current;
        if (!element) return;
        const sign = element.ownerDocument.defaultView?.getComputedStyle(element).direction === "rtl" ? -1 : 1;
        element.scrollBy({ left: direction * sign * element.clientWidth * 0.8, behavior: "auto" });
    };
    return <section data-ui="media-rail" aria-label={label} className={cn("min-w-0", className)}>
        <div className="mb-3 flex items-center justify-between gap-3">
            <span className="text-sm font-medium">{label}</span>
            <div className="flex gap-1">
                <Button variant="ghost" size="icon" className="min-h-11 min-w-11" aria-label={`${label} 이전 항목 보기`} disabled={!items.length} onClick={() => move(-1)}>←</Button>
                <Button variant="ghost" size="icon" className="min-h-11 min-w-11" aria-label={`${label} 다음 항목 보기`} disabled={!items.length} onClick={() => move(1)}>→</Button>
            </div>
        </div>
        <div ref={rail} role="group" aria-label={`${label} 선택`} className="flex min-w-0 snap-x snap-mandatory gap-3 overflow-x-auto pb-2">
            {items.map(item => <button key={item.id} type="button" aria-pressed={value === item.id} onClick={() => onValueChange(item.id)} className={cn("w-36 shrink-0 snap-start rounded-sm border border-transparent bg-transparent p-1 text-left text-sm text-foreground focus-visible:outline-2 focus-visible:outline-focus", value === item.id && "border-accent bg-surface-subtle")}>
                <span className="block overflow-hidden rounded-sm">{item.preview}</span>
                <span className="mt-2 block [overflow-wrap:anywhere]">{item.label}</span>
            </button>)}
            {!items.length && <p className="text-sm text-muted">표시할 항목이 없습니다.</p>}
        </div>
    </section>;
}
